import{z as i,x as s,o as l,c as B,q as t,j as o,D as e,d as r,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"KV 卸载到 CPU / 远端","description":"","frontmatter":{"title":"KV 卸载到 CPU / 远端","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-offload.md","filePath":"llm/kv-offload.md","lastUpdated":1791063341000}'),p={name:"llm/kv-offload.md"};function d(m,a,P,h,C,f){const E=s("Mermaid");return l(),B("div",null,[a[2]||(a[2]=t('<h1 id="kv-卸载到-cpu-远端" tabindex="-1">KV 卸载到 CPU / 远端 <a class="header-anchor" href="#kv-卸载到-cpu-远端" aria-label="Permalink to &quot;KV 卸载到 CPU / 远端&quot;">​</a></h1><div class="epigraph"><p>HBM 装不下的不是权重就是过去的键值；把冷的那截搬到主机或更远的地方，换的是带宽，不是公式里的项消失。</p><footer>—— 对照 Sheng 等 FlexGen 把权重、激活与 KV 放进 CPU/磁盘层级，以及服务栈里按块换出的实践</footer></div><p><a href="/llm/multi-turn-prefix">上一课</a>把多轮写成严格的前缀加长：第 \\(t\\ge 2\\) 轮本应只预填充新用户话，助手输出必须进索引。缺口是容量：热会话 pin 住之后，空闲与被抢占的 KV 仍可能先于权重把 HBM 顶满；减头、量化、滑窗缩小的是「必须常驻」的那一份，还没回答暂时不用的块住哪。本课钉卸载：冷键值搬到 CPU / 磁盘 / 远端，可见集不变、住所变了。不重讲多轮命中路径。后课窗口淘汰默认已经分清「搬走」与「删掉」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多轮命中省的是预填充；空闲会话的 KV 仍可能把 HBM 坐穿。一次解码要读当前层全部驻留 KV。若它们都在 HBM，瓶颈是显存带宽；若一部分在 CPU，瓶颈变成 PCIe（或 CXL）。后者比前者慢一个数量级以上：HBM 以 TB/s 计，PCIe 4.0 ×16 大约数十 GB/s。把整层 KV 每步从 CPU 拉上来，生成一个 token 的时间会被传输钉死，算力闲着。所以卸载能成立，必须满足至少一条：不是每步都用到被卸的那部分（例如已抢占的请求、还未轮到的层、滑窗外本就不会读的块）；或者传输能与别的计算重叠，且传输量小于重叠窗口的算力。</p><p>在线与离线的目标不同。FlexGen 一类系统接受高延迟，用精心安排的调度把 GPU 算满，换单卡吞吐；聊天服务不能让用户等一次磁盘往返才出下一个字。于是同样叫「offload」，产品形态是两种：吞吐导向的多层流水，与延迟导向的「只换出被抢占或空闲会话的块」。</p><p><span class="marginnote">数字实例：HBM 带宽按 3 TB/s 计，PCIe 4.0 x16 约 32 GB/s，相差约百倍。一层 KV 若是 128 MB，从 HBM 读约 0.04 ms，走 PCIe 要约 4 ms——若每步都要拉，一个字还没算就先等了 4 ms，这就是「传输钉死生成」的量级。</span></p><p><span class="marginnote">卸载不增加模型记得的内容。它只是把已有 KV 的住所改了。窗口外已经丢掉的键，卸到 CPU 也找不回来——那是淘汰，不是卸载。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="按层、按请求、按块" tabindex="-1">按层、按请求、按块 <a class="header-anchor" href="#按层、按请求、按块" aria-label="Permalink to &quot;按层、按请求、按块&quot;">​</a></h3><p>三种切法。按层：算第 \\(\\ell\\) 层时，只保证该层 KV 在 HBM，前后层放主机，算完换下一批。这与训练时的激活检查点类似，预填充长序列时有用，解码每步都要过所有层，层间换入换出会变成每步全模型走一遍 PCIe。按请求：把暂停、低优先级或长尾会话的整份 KV 赶出 GPU，恢复时再拉回。这是连续批处理里抢占的自然延伸。按块：与 <a href="/llm/paged-kv-block-size">分页 KV</a> 同一套块表，物理槽的后端可以是 HBM 或 CPU 页，注意力核或调度器在缺页时触发拷贝。粒度最细，也最能与 <a href="/llm/prefix-caching">前缀缓存</a> 共用同一块 ID。</p><p>FlexGen 的贡献是把权重、激活、KV 的存放一起规划，并用交错调度让 PCIe 与计算重叠，而不是「显存不够就整模型 offload」的朴素实现。它证明：在单卡、大模型、追求吞吐时，CPU 甚至磁盘上的 KV 可以被喂饱 GPU。它不证明：同一套调度能满足多租户低延迟。</p><h3 id="带宽不等式" tabindex="-1">带宽不等式 <a class="header-anchor" href="#带宽不等式" aria-label="Permalink to &quot;带宽不等式&quot;">​</a></h3><p>令一步解码要读的 KV 字节为 \\(M\\)，链路带宽为 \\(B_{\\mathrm{io}}\\)，重叠窗口里 GPU 还能做的其他计算时间为 \\(t_{\\mathrm{comp}}\\)。若 \\(M / B_{\\mathrm{io}} \\gt t_{\\mathrm{comp}}\\) 且这些字节都在远端，则 TPOT 的下界就是传输时间。减 \\(M\\) 的手段：GQA、量化、只拉本步可见窗口、层间流水只拉下一层。增 \\(t_{\\mathrm{comp}}\\) 的手段：更大的批次（别的请求还在 HBM 上算）、把卸载请求从交互池里拿开。远端若是另一台机器，还要加序列化、RDMA 与尾延迟，不等式更紧。</p>',14)),(l(),o(A,null,{default:e(()=>[n(E,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20HBM%5B%22%E7%83%AD%20KV%20%E5%9C%A8%20HBM%22%5D%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%A0%B8%22%5D%0A%20%20CPU%5B%22%E5%86%B7%20KV%20%E5%9C%A8%20CPU%20%2F%20NVMe%22%5D%20--%3E%7C%22%E7%BC%BA%E9%A1%B5%E6%8B%B7%E8%B4%9D%22%7C%20HBM%0A%20%20PIN%5B%22%E6%AD%A3%E5%9C%A8%E8%A7%A3%E7%A0%81%E7%9A%84%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20HBM%0A%20%20PRE%5B%22%E8%A2%AB%E6%8A%A2%E5%8D%A0%E7%9A%84%E4%BC%9A%E8%AF%9D%22%5D%20--%3E%20CPU%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="只读换出与预取" tabindex="-1">只读换出与预取 <a class="header-anchor" href="#只读换出与预取" aria-label="Permalink to &quot;只读换出与预取&quot;">​</a></h3><p>换出的正确性依赖块内容不变。KV 一旦写完（该 token 的键值已追加），直到被淘汰前都是只读的，所以搬到 CPU 不必写回脏页——这一点比训练激活卸载更简单。写路径只发生在追加新 token 时，新块应在 HBM 分配；冷的是旧块。前缀共享时，热请求与冷请求可能指向同一物理块：引用计数必须跨存储层，不能把仍被 GPU 请求指着的块卸走。</p><p><span class="marginnote">直觉类比：KV 追加像往活页夹里插页——插完的页就不会再改。把一叠旧页搬去档案室，不需要检查「有没有涂改」，只需要确认没人正要翻它；引用计数就是「谁还翻着这页」的登记簿。</span></p><p>预取是唯一能把延迟藏起来的机制。调度器若知道下一层、下一个时间步、下一个即将 resume 的请求，就可以在当前 GEMM 时把下一包 KV DMA 进来。预取错误（猜错下一请求）会挤占 HBM，比不预取更糟。因此交互式服务往往只对「即将 resume 的那一条」做预取，而不是盲目把 CPU 上所有块往卡上灌。</p>',5)),(l(),o(A,null,{default:e(()=>[n(E,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E9%A2%84%E6%B5%8B%3A%20%E4%B8%8B%E4%B8%80%E6%AD%A5%E8%A6%81%E5%93%AA%E4%B8%80%E5%8C%85%20KV%22%5D%20--%3E%20P%7B%22%E9%A2%84%E6%B5%8B%E5%AF%B9%E5%90%97%3F%22%7D%0A%20%20P%20--%3E%7C%22%E5%AF%B9%22%7C%20H%5B%22%E8%B6%81%E5%BD%93%E5%89%8D%20GEMM%20%E5%9C%A8%E7%AE%97%2C%20%E5%90%8E%E5%8F%B0%20DMA%20%E9%A2%84%E5%8F%96%22%5D%0A%20%20H%20--%3E%20G%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%A6%81%E7%94%A8%E6%97%B6%E5%B7%B2%E5%9C%A8%20HBM%3A%20%E4%BC%A0%E8%BE%93%E8%A2%AB%E8%97%8F%E8%BF%9B%E8%AE%A1%E7%AE%97%22%5D%0A%20%20P%20--%3E%7C%22%E9%94%99%22%7C%20W%5B%22%E7%8C%9C%E9%94%99%3A%20%E7%99%BD%E5%8D%A0%20HBM%2C%20%E6%AF%94%E4%B8%8D%E9%A2%84%E5%8F%96%E6%9B%B4%E7%B3%9F%22%5D%0A%20%20W%20--%3E%20F%5B%22%E4%BA%A4%E4%BA%92%E6%9C%8D%E5%8A%A1%E5%9B%A0%E6%AD%A4%E5%8F%AA%E9%A2%84%E5%8F%96%E5%8D%B3%E5%B0%86%20resume%20%E7%9A%84%E9%82%A3%E4%B8%80%E6%9D%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">量化后再卸载，传输的字节变少，PCIe 税下降。先 INT8 再卸，通常比先卸 FP16 更划算。精度故事见 <a href="/llm/kv-int8-fp8">KV INT8 / FP8</a>，不要在卸的路上再随手改变量化轴。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「支持 CPU offload」写进低延迟 SLA。它适合：单卡跑过大模型的离线批处理；在线服务里被抢占的会话；端侧把长对话的远历史放到 DRAM。不适合：每条交互请求的默认路径。测量必须看 TPOT 的分位数，平均值会被仍在 HBM 上的请求粉饰。</p><p><span class="marginnote">术语翻译：SLA 是服务向用户承诺的「延迟合同」，例如「95% 的请求每个字 50 ms 内吐出」。CPU 往返动辄几毫秒到几十毫秒，把 offload 写进这种合同，等于把偶发卡顿变成违约记录。</span></p><p>远端节点上的 KV 还有一致性与安全问题。多副本不要各卸各的再各算各的，除非接受前缀缓存失效。租户隔离在主机内存同样适用，不能因为「已经离开 GPU」就放松。NVMe 上的 KV 会把尾延迟打到十毫秒以上，只适合完全离线。</p><p>与窗口淘汰的分工：淘汰改变模型可见集，卸载不改变。先决定模型还能否读这些键，再决定它们住在哪一层存储。把本应淘汰的块卸到 CPU「以备将来」，是在用主机内存假装长记忆，注意力核若已经看不见它们，这份拷贝只是垃圾。</p><p><span class="marginnote">FlexGen 的数字不能直接抄到在线网关。它的目标函数是吞吐，调度可以重排整个离线批次。网关的目标函数是排队与 TPOT，重排空间小得多。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KV 卸载把冷键值放到 CPU / 磁盘 / 远端，不改变注意力可见集，只改变住所。</li><li>每步都要从远端拉全量 KV 时，PCIe 会成为 TPOT 下界；必须靠抢占粒度、层流水或与计算重叠。</li><li>FlexGen 展示了单卡、吞吐导向的多层规划；在线服务更常见的是按分页块换出被抢占会话。</li><li>已写完的 KV 只读，换出无需写回；新 token 仍在 HBM 追加。</li><li>共享块的引用计数要跨存储层；量化可以降低传输字节。</li><li>低延迟交互不要把 offload 当默认路径；与淘汰分开记账。</li><li>出处：Sheng 等，<em>FlexGen: High-Throughput Generative Inference of Large Language Models with a Single GPU</em>，ICML 2023；块级换出建立在 Kwon 等 PagedAttention 的块表之上。</li></ul>',9))])}const u=i(p,[["render",d]]);export{c as __pageData,u as default};
